// Given: draggable handles for "drag and see" visuals. Do not edit this file.
// Uses pointer events, so mouse, pen and touch all work.
import type { Vec2 } from "../math/vec2";
import { screenToWorld, worldToScreen, type View } from "../render/view";

export type Handle = {
  /** Current world position of the handle. */
  get(): Vec2;
  /** Called with the new world position while dragging. */
  set(p: Vec2): void;
  /** Grab radius in CSS pixels. Default 14 (comfortable on touch). */
  radius?: number;
};

/** Makes handles draggable on the view's canvas. Returns a function that removes the listeners. */
export function makeDraggable(view: View, handles: Handle[], onChange: () => void): () => void {
  const canvas = view.canvas;
  canvas.style.touchAction = "none";
  let active: Handle | null = null;

  const local = (e: PointerEvent): Vec2 => {
    const r = canvas.getBoundingClientRect();
    return { x: e.clientX - r.left, y: e.clientY - r.top };
  };

  const hit = (s: Vec2): Handle | null => {
    let best: Handle | null = null;
    let bestDist = Infinity;
    for (const h of handles) {
      const p = worldToScreen(view, h.get());
      const d = Math.hypot(p.x - s.x, p.y - s.y);
      if (d <= (h.radius ?? 14) && d < bestDist) {
        best = h;
        bestDist = d;
      }
    }
    return best;
  };

  const down = (e: PointerEvent) => {
    active = hit(local(e));
    if (active) {
      canvas.setPointerCapture(e.pointerId);
      e.preventDefault();
    }
  };
  const move = (e: PointerEvent) => {
    const s = local(e);
    if (active) {
      active.set(screenToWorld(view, s));
      onChange();
    } else {
      canvas.style.cursor = hit(s) ? "grab" : "default";
    }
  };
  const up = (e: PointerEvent) => {
    if (active && canvas.hasPointerCapture(e.pointerId)) canvas.releasePointerCapture(e.pointerId);
    active = null;
  };

  canvas.addEventListener("pointerdown", down);
  canvas.addEventListener("pointermove", move);
  canvas.addEventListener("pointerup", up);
  canvas.addEventListener("pointercancel", up);
  return () => {
    canvas.removeEventListener("pointerdown", down);
    canvas.removeEventListener("pointermove", move);
    canvas.removeEventListener("pointerup", up);
    canvas.removeEventListener("pointercancel", up);
  };
}
